<script setup>import { computed,onMounted,ref } from 'vue';import { api } from '../api/oa';const contacts=ref([]),keyword=ref('');onMounted(async()=>contacts.value=await api.contacts());const filtered=computed(()=>contacts.value.filter(x=>(x.fullName+x.departmentName+x.position).includes(keyword.value)))</script>
<template><div class="page safe-top"><h1 class="page-title">组织通讯录</h1><van-search v-model="keyword" shape="round" placeholder="搜索姓名、部门或职位"/><section v-for="person in filtered" :key="person.id" class="person card"><div class="avatar">{{person.fullName.slice(0,1)}}</div><div class="info"><div class="list-title">{{person.fullName}} <span class="tag">{{person.departmentName}}</span></div><div class="muted">{{person.position || '员工'}} · {{person.phone || '暂无电话'}}</div></div><a v-if="person.phone" :href="`tel:${person.phone}`"><van-icon name="phone-o"/></a></section><div v-if="!filtered.length" class="empty">没有找到联系人</div></div></template>
<style scoped>.van-search{padding:0 0 16px;background:transparent}.person{display:flex;align-items:center;gap:13px}.avatar{width:44px;height:44px;display:grid;place-items:center;border-radius:14px;background:#e2f1f0;color:#126e82;font-weight:700}.info{flex:1}.person a{font-size:24px;color:#126e82}.tag{font-weight:400;margin-left:5px}</style>
